import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  Link,
  List,
  ListItem,
  ListItemText,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalance as BankIcon,
  Analytics as AnalyticsIcon,
  Api as ApiIcon,
  Business as BusinessIcon,
  CheckCircleOutline as CheckIcon,
  Code as CodeIcon,
  FactCheck as VerificationIcon,
  Groups as EcosystemIcon,
  Handshake as HandshakeIcon,
  Hub as WorkflowIcon,
  IntegrationInstructions as IntegrationIcon,
  Public as InstitutionalIcon,
  VerifiedUser as AuditorIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import {
  ECOSYSTEM_BENEFITS,
  PARTNER_CONTACT_EMAIL,
  PARTNER_ECOSYSTEM_FLOW_STEPS,
  PARTNER_ECOSYSTEM_INTRO,
  PARTNER_PROGRAM_SUMMARY,
  PARTNER_TYPES,
  PARTNERS_PAGE,
  PARTNERS_PAGE_CTA,
  PARTNERS_PAGE_SECTIONS,
} from '../../constants/partnerProgram';
import { useRegistration } from '../../context/RegistrationContext';
import { TopicIconBadge } from '../shared/TopicIconBadge';
import MarketingHeading from '../shared/MarketingHeading';

const PARTNER_TYPE_ICONS: Record<string, React.ElementType> = {
  bank_platform: BankIcon,
  anchor_enterprise: BusinessIcon,
  auditor: AuditorIcon,
  verification_agency: VerificationIcon,
  integration_partner: IntegrationIcon,
  api_starter: CodeIcon,
  institutional: InstitutionalIcon,
};

const PartnersPage: React.FC = () => {
  const theme = useTheme();
  const { isRegistered } = useRegistration();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
        <TopicIconBadge size="large">
          <HandshakeIcon />
        </TopicIconBadge>
        <Box>
          <MarketingHeading level="h1">
            {PARTNERS_PAGE.title}
          </MarketingHeading>
          <Typography variant="subtitle1" color="primary.main" sx={{ fontWeight: 700 }}>
            {PARTNERS_PAGE.subtitle} · {PARTNERS_PAGE.tagline}
          </Typography>
        </Box>
      </Stack>

      <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 720 }}>
        {PARTNER_PROGRAM_SUMMARY}
      </Typography>

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 2.5 },
          mb: 3,
          borderStyle: 'dashed',
          borderColor: alpha(theme.palette.primary.main, 0.35),
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.06 : 0.04),
        }}
      >
        <Stack direction="row" spacing={1.5} alignItems="flex-start">
          <EcosystemIcon color="primary" sx={{ mt: 0.25 }} />
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.75 }}>
              {PARTNERS_PAGE_SECTIONS.ecosystem.title}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {PARTNER_ECOSYSTEM_INTRO}
            </Typography>
          </Box>
        </Stack>
      </Paper>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <WorkflowIcon color="primary" />
        <MarketingHeading level="h2">
          {PARTNERS_PAGE_SECTIONS.ecosystem.workflowTitle}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {PARTNERS_PAGE_SECTIONS.ecosystem.workflowLead}
      </Typography>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {PARTNER_ECOSYSTEM_FLOW_STEPS.map((step) => (
          <Grid item xs={12} sm={6} md={3} key={step.step}>
            <Paper
              variant="outlined"
              sx={{
                p: 2,
                height: '100%',
                borderColor: alpha(theme.palette.primary.main, isDark ? 0.4 : 0.25),
              }}
            >
              <Chip
                label={step.step}
                size="small"
                color="primary"
                variant="outlined"
                sx={{ mb: 1, fontWeight: 700 }}
              />
              <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
                {step.title}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {step.description}
              </Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <HandshakeIcon color="primary" />
        <MarketingHeading level="h2">
          {PARTNERS_PAGE_SECTIONS.partnerTypes.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {PARTNERS_PAGE_SECTIONS.partnerTypes.lead}
      </Typography>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {PARTNER_TYPES.map((partnerType) => {
          const Icon = PARTNER_TYPE_ICONS[partnerType.id] || AnalyticsIcon;
          return (
            <Grid item xs={12} sm={6} key={partnerType.id}>
              <Card variant="outlined" sx={{ height: '100%' }}>
                <CardContent>
                  <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
                    <TopicIconBadge size="small">
                      <Icon fontSize="small" />
                    </TopicIconBadge>
                    <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                      {partnerType.title}
                    </Typography>
                  </Stack>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                    {partnerType.summary}
                  </Typography>
                  <List dense disablePadding sx={{ mb: 1.5 }}>
                    {partnerType.capabilities.map((capability) => (
                      <ListItem key={capability.slice(0, 40)} disableGutters sx={{ py: 0.25 }}>
                        <CheckIcon color="primary" fontSize="small" sx={{ mr: 1, flexShrink: 0 }} />
                        <ListItemText
                          primary={capability}
                          primaryTypographyProps={{ variant: 'body2', color: 'text.secondary' }}
                        />
                      </ListItem>
                    ))}
                  </List>
                  <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 700, display: 'block', mb: 0.5 }}>
                    Role in the ecosystem
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {partnerType.ecosystemRole}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <EcosystemIcon color="primary" />
        <MarketingHeading level="h2">
          {PARTNERS_PAGE_SECTIONS.benefits.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {PARTNERS_PAGE_SECTIONS.benefits.lead}
      </Typography>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {ECOSYSTEM_BENEFITS.map((benefit) => (
          <Grid item xs={12} md={4} key={benefit.id}>
            <Card variant="outlined" sx={{ height: '100%' }}>
              <CardContent>
                <Chip
                  label={benefit.stakeholder}
                  size="small"
                  color="primary"
                  variant="outlined"
                  sx={{ mb: 1.5, fontWeight: 700 }}
                />
                <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1.5 }}>
                  {benefit.headline}
                </Typography>
                <List dense disablePadding>
                  {benefit.benefits.map((item) => (
                    <ListItem key={item.slice(0, 40)} disableGutters sx={{ py: 0.25 }}>
                      <CheckIcon color="primary" fontSize="small" sx={{ mr: 1, flexShrink: 0 }} />
                      <ListItemText
                        primary={item}
                        primaryTypographyProps={{ variant: 'body2', color: 'text.secondary' }}
                      />
                    </ListItem>
                  ))}
                </List>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
        <ApiIcon color="primary" />
        <MarketingHeading level="h2">
          {PARTNERS_PAGE_SECTIONS.apiDocumentation.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {PARTNERS_PAGE_SECTIONS.apiDocumentation.lead}
      </Typography>
      <Card variant="outlined" sx={{ mb: 4 }}>
        <CardContent>
          <Stack
            direction={{ xs: 'column', sm: 'row' }}
            spacing={2}
            alignItems={{ xs: 'flex-start', sm: 'center' }}
            justifyContent="space-between"
          >
            <Box>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
                {PARTNERS_PAGE_CTA.apiTeaserTitle}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {PARTNERS_PAGE_CTA.apiTeaserDescription}
              </Typography>
            </Box>
            <Button
              component={RouterLink}
              to="/partners/api-documentation"
              variant="outlined"
              startIcon={<ApiIcon />}
            >
              {PARTNERS_PAGE_CTA.apiDocsLabel}
            </Button>
          </Stack>
        </CardContent>
      </Card>

      <Divider sx={{ mb: 3 }} />

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 3 },
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
          alignItems: { xs: 'flex-start', sm: 'center' },
          justifyContent: 'space-between',
          gap: 2,
        }}
      >
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
            {PARTNERS_PAGE_CTA.title}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            {PARTNERS_PAGE_CTA.description}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Contact{' '}
            <Link href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20enquiry`} sx={{ fontWeight: 600 }}>
              {PARTNER_CONTACT_EMAIL}
            </Link>
            . {PARTNERS_PAGE_CTA.assistanceNote}
          </Typography>
        </Box>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
          {!isRegistered && (
            <Button component={RouterLink} to="/login" variant="outlined">
              {PARTNERS_PAGE_CTA.signInLabel}
            </Button>
          )}
          <Button
            component={RouterLink}
            to={isRegistered ? '/dashboard' : '/register?type=partner'}
            variant="contained"
          >
            {isRegistered ? PARTNERS_PAGE_CTA.workspaceLabel : PARTNERS_PAGE_CTA.registerLabel}
          </Button>
          <Button component={RouterLink} to="/partners/api-documentation" variant="text">
            {PARTNERS_PAGE_CTA.apiDocsLabel}
          </Button>
        </Stack>
      </Paper>
    </Box>
  );
};

export default PartnersPage;
